visualProgram.init:
const R=params.resistance;
const C=params.capacitance;
const Vs=params.voltage;
return {time:0,R:R,C:C,Vs:Vs,points:[]};

visualProgram.step:
state.time+=dt*params.timeScale;
const tau=state.R*state.C;
const v=state.Vs*(1-Math.exp(-state.time/tau));
if(state.points.length<200) state.points.push({t:state.time,v:v});

visualProgram.draw:
const M=32; // margin
const bg="#0b1729";
// background (optional)
// draw circuit on left 45% of canvas
const circuitW=width*0.45;
const cx=M;
const cy=height/2;
const spacing=(circuitW-2*M)/4;
// positions
const batX=cx+spacing*0.5;
const resX=cx+spacing*1.5;
const capX=cx+spacing*2.5;
const lineY=cy;
const lineH=4;
// helper to draw horizontal segment
const hline=(x1,x2)=>{paint.line(x1,lineY,x2,lineY,"#fff",lineH);};
// left lead
hline(M,batX-20);
// battery symbol (two lines)
paint.line(batX-20,lineY-15,batX-20,lineY+15,"#fff",2);
paint.line(batX-10,lineY-8,batX-10,lineY+8,"#fff",2);
// plus sign
paint.line(batX-20,lineY,batX-10,lineY,"#fff",2);
// right lead of battery
hline(batX,batX+20);
// resistor (rectangle)
paint.rect(resX-20,lineY-10,40,20,"#555");
hline(resX+20,resX+20+spacing-20);
// capacitor (two plates)
const capXmid=resX+spacing-20;
paint.line(capXmid-5,lineY-15,capXmid-5,lineY+15,"#fff",2);
paint.line(capXmid+5,lineY-15,capXmid+5,lineY+15,"#fff",2);
hline(capXmid+5,capXmid+5+spacing-20);
// right lead to node (end)
hline(capXmid+5+spacing-20,width-M);
// labels
paint.text(batX-15,lineY-20,"Nguồn","#fff",12);
paint.text(resX,lineY-25,"R","#fff",12);
paint.text(capXmid,lineY-25,"C","#fff",12);
// draw graph on right side
const gx=width*0.45+M;
const gw=width*0.55-2*M;
const gh=height-2*M;
const gx0=gx;
const gy0=height-M;
// axes
paint.line(gx0,gy0,gx0+gw,gy0,"#fff",2); // x axis
paint.line(gx0,gy0,gx0,gy0-gh,"#fff",2); // y axis
// axis labels
paint.text(gx0+gw/2,gy0+20,"Thời gian (s)","#fff",12);
paint.text(gx0-30,gy0-gh/2,"V_C (V)","#fff",12);
// scaling
const maxTime=state.time>0?state.time:params.timeScale*20; // ensure non‑zero
const xScale=gw/maxTime;
const yScale=gh/state.Vs;
// plot curve
for(let i=1;i<state.points.length;i++){
  const p0=state.points[i-1];
  const p1=state.points[i];
  const x0=gx0+p0.t*xScale;
  const y0=gy0-p0.v*yScale;
  const x1=gx0+p1.t*xScale;
  const y1=gy0-p1.v*yScale;
  paint.line(x0,y0,x1,y1,"#0f0",2);
}
// moving marker
if(state.points.length>0){
  const p=state.points[state.points.length-1];
  const mx=gx0+p.t*xScale;
  const my=gy0-p.v*yScale;
  paint.circle(mx,my,5,"#ff0");
  paint.text(mx+8,my-8,`V=${p.v.toFixed(2)}V`,"#ff0",12);
}
